={{ (() => { 
const literal = value => {
  if (value === null) return 'null';
  if (typeof value === 'string') return "'" + value.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/[\u0000-\u001f\u007f]/g, c => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0')) + "'";
  if (typeof value === 'boolean') return String(value);
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (Array.isArray(value)) return '[' + value.map(literal).join(',') + ']';
  if (typeof value === 'object' && value !== null) return '{' + Object.entries(value).map(([key, val]) => {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) throw new Error('Invalid Cypher map key');
    return key + ':' + literal(val);
  }).join(',') + '}';
  throw new Error('Unsupported Cypher value');
};
const values = {"bird_taxa": literal($json["bird_taxa"]),"event_date_end": literal($json["event_date_end"]),"media": literal($json["media"]),"observations": literal($json["observations"]),"pipeline_id": literal($json["pipeline_id"]),"quarantine": literal($json["quarantine"]),"quarantine_count": literal($json["quarantine_count"]),"retrieved_at": literal($json["retrieved_at"]),"run_id": literal($json["run_id"]),"source_count": literal($json["source_count"]),"source_release": literal($json["source_release"]),"taxon_count": literal($json["taxon_count"]),"taxon_links": literal($json["taxon_links"])}; return "MERGE (run:IngestionRun {id: $run_id}) SET run.pipeline_id = $pipeline_id, run.started_at = $retrieved_at, run.source_release = $source_release, run.status = 'loading', run.source_count = $source_count, run.taxon_count = $taxon_count, run.quarantine_count = $quarantine_count WITH run CALL { WITH run MERGE (concept_set:TaxonConceptSet {id: 'rg:concept-set:gbif-current'}) SET concept_set.title = 'GBIF taxonomic backbone', concept_set.version = 'mutable-current', concept_set.source_uri = 'https://www.gbif.org/species/search', concept_set.retrieved_at = $retrieved_at MERGE (taxonomy_dataset:SourceDataset {id: 'gbif-dataset:taxonomic-backbone'}) SET taxonomy_dataset.name = 'GBIF taxonomic backbone', taxonomy_dataset.provider = 'GBIF', taxonomy_dataset.version = 'mutable-current', taxonomy_dataset.landing_uri = 'https://www.gbif.org/species/search', taxonomy_dataset.policy_status = 'allowed' MERGE (taxonomy_license:License {id: 'https://creativecommons.org/licenses/by/4.0/'}) SET taxonomy_license.license_uri = 'https://creativecommons.org/licenses/by/4.0/', taxonomy_license.policy_status = 'allowed' MERGE (taxonomy_dataset)-[:LICENSED_UNDER]->(taxonomy_license) MERGE (concept_set)-[:FROM_DATASET]->(taxonomy_dataset) WITH run, concept_set UNWIND $bird_taxa AS row MERGE (taxon:ExternalTaxonConcept {id: row.id}) SET taxon:BirdTaxon, taxon.provider = row.provider, taxon.extern