= $run_id, item.first_seen_at = $retrieved_at SET item.external_id = row.external_id, item.stage = row.stage, item.reason_codes = row.reason_codes, item.source_uri = row.source_uri, item.last_seen_run_id = $run_id, item.last_seen_at = $retrieved_at, item.resolution_status = 'open' MERGE (run)-[:QUARANTINED]->(item) RETURN count(*) AS loaded_quarantine } SET run.status = 'succeeded', run.finished_at = datetime(), run.taxon_count = loaded_taxa, run.taxon_link_count = loaded_taxon_links, run.observation_count = loaded_observations, run.media_count = loaded_media MERGE (state:IngestState {id: $pipeline_id}) SET state.active_release = $source_release, state.last_successful_run_id = $run_id, state.last_successful_at = datetime(), state.event_date_end = $event_date_end RETURN loaded_taxa, loaded_taxon_links, loaded_observations, loaded_media, loaded_quarantine, state.active_release".replace(/\$([A-Za-z_][A-Za-z0-9_]*)/g, (_, key) => values[key]); })() }}

